export const DecimaltoDMS=t=>{const e=Math.abs(t),a=Math.floor(e),o=60*(e-a),r=Math.floor(o),n=Math.floor(60*(o-r));return{deg:a,min:r,sec:n,text:`${a}° ${r}′ ${n}″`,html:`${a}&#176; ${r}&#180; ${n}&#733;`}};export const DMSToDecimal=(t,e,a,o)=>{let r=Number(t)+Number(e)/60+Number(a)/3600;return"S"!==o&&"W"!==o||(r*=-1),r};export const formatDecimalToDMS=(t,e)=>{const a=DecimaltoDMS(t),o=t>=0?"N":"S",r=DecimaltoDMS(e),n=e>=0?"E":"W";return{lat:a.text,lng:r.text,latCardinal:o,lngCardinal:n,text:`${a.text} ${o} , ${r.text} ${n}`,html:`${a.html} ${o} , ${r.html} ${n}`}};export const formatDMSToDecimal=(t,e)=>{let a=t.split(/[^\d\w]+/);const o=DMSToDecimal(a[0],a[1],a[2],a[3]);a=e.split(/[^\d\w]+/);const r=DMSToDecimal(a[0],a[1],a[2],a[3]);return{lat:Number(o),lng:Number(r),text:`${o},${r}`}};export const haversineDistance=(t,e,a,o)=>{const r=t=>t*Math.PI/180,n=r(a-t),l=r(o-e),s=Math.sin(n/2)*Math.sin(n/2)+Math.cos(r(t))*Math.cos(r(a))*Math.sin(l/2)*Math.sin(l/2);return 6378137*(2*Math.atan2(Math.sqrt(s),Math.sqrt(1-s)))};export const polylineSegment=(t,e,a,o=1e-5)=>{let r=-1,n=-1;for(let l=0;l<t.length;l++){const s=t[l],c=s.lat||s[0],i=s.lng||s[1],M=e.lat||e[0],h=e.lng||e[1],m=a.lat||a[0],D=a.lng||a[1];Math.abs(c-M)<o&&Math.abs(i-h)<o&&(r=l),Math.abs(c-m)<o&&Math.abs(i-D)<o&&(n=l)}return-1===r||-1===n?(console.warn("Start or end coordinate not found in polyline"),[]):(r>n&&([r,n]=[n,r]),t.slice(r,n+1))};export const reverseCoordinates=t=>Array.isArray(t)?"number"==typeof t[0]?[t[1],t[0]]:t.map((t=>reverseCoordinates(t))):t;